// Extract lead fields whether payload comes from Meta Lead Ads trigger or direct Webhook
const body = $input.first().json.body || $input.first().json;

let fullName = body.fullName || body.full_name || body.name || '';
let phoneNumber = body.phoneNumber || body.phone_number || body.phone || body.mobile || '';
let email = body.email || body.email_address || '';

const customFields = {};

// Handle standard Facebook Graph API / Meta field_data array
if (Array.isArray(body.field_data)) {
  for (const field of body.field_data) {
    const name = (field.name || '').toLowerCase();
    const val = Array.isArray(field.values) ? field.values.join(', ') : (field.values || '');
    if (!val) continue;

    if (!fullName && (name.includes('name') || name === 'full_name')) {
      fullName = val;
    } else if (!phoneNumber && (name.includes('phone') || name.includes('mobile'))) {
      phoneNumber = val;
    } else if (!email && name.includes('email')) {
      email = val;
    } else {
      customFields[field.name] = val;
    }
  }
}

if (!fullName && (body.first_name || body.last_name)) {
  fullName = [body.first_name, body.last_name].filter(Boolean).join(' ');
}

return [{
  json: {
    fullName: fullName || (email ? 'Lead (' + email.split('@')[0] + ')' : 'Meta Lead'),
    phoneNumber: phoneNumber || 'Not provided',
    email: email || undefined,
    campaignName: body.campaign_name || body.campaignName || body.campaign || undefined,
    adSetName: body.adset_name || body.adSetName || undefined,
    adName: body.ad_name || body.adName || undefined,
    formName: body.form_name || body.formName || undefined,
    platform: body.platform || 'Meta (Facebook / Instagram)',
    metaLeadId: body.lead_id || body.metaLeadId || body.id || undefined,
    notes: body.notes || undefined,
    customFields: Object.keys(customFields).length > 0 ? customFields : undefined
  }
}];
